import React from 'react';

import { tooltipDuration, formattedTimeframe } from './styles.sty.js';
import { FormattedTimeframe } from '../../../../../../formatters/timeframe/FormattedTimeframe.js';
import { DurationChipAtom } from '../../../tooltip-atoms/components/DurationChipAtom.js';
import { TooltipDurationProps } from '../../types/ChartTooltip.config.js';

export const TooltipDuration = (props: TooltipDurationProps) => {
  const { from, to, ...rest } = props;

  return (
    <div className={tooltipDuration} {...rest}>
      <DurationChipAtom from={from} to={to} />
      <div className={formattedTimeframe}>
        <FormattedTimeframe from={from} to={to} />
      </div>
    </div>
  );
};

TooltipDuration['displayName'] = 'TooltipDuration';
